import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
FILES=sorted((ROOT/'questions/science').glob('question-science-content-ba-iv-5-*.json'),key=lambda p:int(p.stem.rsplit('-',1)[1]))
ITEMS=[
('功的計算','水平力20 N推箱子沿力方向移動3 m，力對箱子作功多少？',['6 J','17 J','60 J','600 J'],'C','同方向時W=Fd=20×3=60 J。'),
('零功條件','下列哪種情況中，力對物體所作的功為零？',['力與位移同方向','力與位移反方向','力與位移互相垂直','力和位移都不為零且同方向'],'C','W=Fd cosθ；θ=90°時cosθ=0，因此功為零。'),
('負功','箱子向右滑動，摩擦力向左。摩擦力對箱子通常作何種功？',['正功','負功','零功且沒有能量影響','無法判定方向'],'B','摩擦力與位移反方向，作負功，使箱子機械能減少並轉為熱。'),
('重力作功','物體在重力作用下由高處落下，重力對物體通常作？',['正功，使重力位能降低','負功，使重力位能增加','零功，因為物體有重量','化學功'],'A','位移向下與重力同方向，重力作正功，重力位能轉為動能。'),
('提物功','人以向上的力將物體等速提升，力對物體作功的結果主要是？',['物體重力位能增加','物體質量消失','物體溫度必定下降','力沒有作功'],'A','向上力與位移同方向，輸入功增加物體的重力位能；等速表示合力可能為零，但手的力仍作正功。'),
('功與動能','合力對物體作正功時，依功—能定理，物體的動能通常？',['增加','減少','一定為零','與功無關'],'A','合力所作的淨功等於動能變化量，正功代表動能增加。'),
('單位判讀','功的國際單位焦耳 J 等於哪個組合？',['N/m','N·m','kg/m','m/s'],'B','W=Fd，力的單位N乘位移m，得到N·m，定義為J。'),
('抵抗力作功','人推牆但牆沒有位移，即使人感到疲累，牆受到的推力作功為何？',['正功','負功','零功','無限大'],'C','牆的位移為零，W=Fd=0；人的生理能量消耗不等於牆受到的機械功。'),
('斜向力','以斜向上力拉箱子水平前進，該力對箱子的功應使用哪個分量？',['垂直分量','沿位移方向的水平分量','重量分量','摩擦力分量'],'B','功由力在位移方向的分量造成，W=Fd cosθ。'),
('能量轉換','物體受外力作正功而速度增加，最合理的能量說明是？',['外力傳入的能量增加物體動能','能量從物體消失','物體質量必定變大','只有溫度會改變'],'A','正淨功使動能增加，外力輸入的能量轉入物體的運動狀態。'),
]
for p,(topic,prompt,opts,ans,ex) in zip(FILES,ITEMS):
 d=json.loads(p.read_text()); d['prompt']=prompt; d['options']=[{'id':chr(65+i),'text':t} for i,t in enumerate(opts)]; d['answer']={'value':ans,'explanation':ex}; d['solutionStrategy']=f'先判斷力與位移的方向，再使用W=Fd cosθ，最後連結正負功與動能／位能變化；本題聚焦於{topic}。'; d['solutionSteps']=['先圈出力的大小、位移大小與兩者方向。','寫出W=Fd cosθ；同向為正、反向為負、垂直為零。',f'代入數值或依功—能定理判斷，得到答案{ans}。',f'回看解析：{ex}','最後檢查單位是否為J，並區分單一力作功與合力作功。']; d['reviewStatus']='draft'; d['updatedAt']='2026-09-08'; d['provenance']['authoringNote']='依官方課綱與公開會考、公立國中試題所呈現的功、力與位移、正負功及能量改變推理方向獨立改寫；未複製原題文字、選項、圖表或答案；待第二輪 AI／Terra 內容複核。'; p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
